package com.codiebutterfly.schoolrun;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import static com.codiebutterfly.schoolrun.Store.*;

@RestController @RequestMapping("/api/marketplace") public class Marketplace {
 final Store s; final Journeys journeys; final Path uploads;
 Marketplace(Store s,Journeys journeys,@Value("${schoolrun.uploads}")String uploads){this.s=s;this.journeys=journeys;this.uploads=Path.of(uploads);}
 int seats(Object driver){var u=s.one("SELECT * FROM sr_user WHERE id=?",driver);Map<String,Object> profile=s.decode(u.get("profile"));int count=s.db.queryForObject("SELECT count(*) FROM sr_child c JOIN sr_link l ON l.id=c.link_id WHERE l.driver_id=?",Integer.class,driver);return Math.max(0,((Number)profile.get("capacity")).intValue()-count);}
 boolean enabled(Map<String,Object>b,String key){if(b.containsKey(key)&&!(b.get(key) instanceof Boolean))throw error(400,"Invalid matching switch");return !Boolean.FALSE.equals(b.get(key));}
 Map<String,Object> route(Map<String,Object>b){var r=new LinkedHashMap<String,Object>();boolean home=enabled(b,"matchPickupArea"),school=enabled(b,"matchSchool");r.put("limitEnrolment",enabled(b,"limitEnrolment"));r.put("matchPickupArea",home);r.put("matchSchool",school);
 if(home){r.put("area",text(b,"area",300));r.put("homeLat",coordinate(b,"homeLat",90));r.put("homeLng",coordinate(b,"homeLng",180));double radius=coordinate(b,"radiusKm",30);if(radius<1)throw error(400,"Choose a service radius from 1 to 30 km");r.put("radiusKm",radius);}
 if(school){r.put("school",text(b,"school",300));r.put("schoolLat",coordinate(b,"schoolLat",90));r.put("schoolLng",coordinate(b,"schoolLng",180));}return r;}
 boolean matches(Map<String,Object>r,Map<String,Object>b){return (!enabled(r,"matchPickupArea")||RoutePlanner.distance(((Number)r.get("homeLat")).doubleValue(),((Number)r.get("homeLng")).doubleValue(),coordinate(b,"homeLat",90),coordinate(b,"homeLng",180))<=((Number)r.get("radiusKm")).doubleValue())&&(!enabled(r,"matchSchool")||RoutePlanner.distance(((Number)r.get("schoolLat")).doubleValue(),((Number)r.get("schoolLng")).doubleValue(),coordinate(b,"schoolLat",90),coordinate(b,"schoolLng",180))<=1);}
 @GetMapping("/listing") Object listing(@RequestHeader(value="Authorization",required=false)String a){var u=s.user(a);s.role(u,"DRIVER");var rows=s.db.queryForList("SELECT * FROM sr_driver_listing WHERE driver_id=?",u.get("id"));if(rows.isEmpty())return Map.of("available",false,"shareLicence",false,"seats",seats(u.get("id")));var row=rows.get(0);return Map.of("available",row.get("available"),"shareLicence",row.get("share_licence"),"route",s.decode(row.get("route_details")),"seats",seats(u.get("id")));}
 @PutMapping("/listing") @Transactional Object publish(@RequestHeader(value="Authorization",required=false)String a,@RequestBody Map<String,Object>b){var u=s.user(a);s.role(u,"DRIVER");s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",u.get("id"));var r=route(b);boolean available=Boolean.TRUE.equals(b.get("available")),share=Boolean.TRUE.equals(b.get("shareLicence"));s.db.update("DELETE FROM sr_driver_listing WHERE driver_id=?",u.get("id"));s.db.update("INSERT INTO sr_driver_listing VALUES(?,?,?,?)",u.get("id"),available,share,s.encode(r));return listing(a);}
 @PutMapping("/availability") @Transactional Object availability(@RequestHeader(value="Authorization",required=false)String a,@RequestBody Map<String,Object>b){var u=s.user(a);s.role(u,"DRIVER");s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",u.get("id"));if(s.db.update("UPDATE sr_driver_listing SET available=? WHERE driver_id=?",Boolean.TRUE.equals(b.get("available")),u.get("id"))==0)throw error(400,"Publish your service route first");return listing(a);}
 @PostMapping("/search") Object search(@RequestHeader(value="Authorization",required=false)String a,@RequestBody Map<String,Object>b){s.role(s.user(a),"PARENT");for(String k:List.of("homeLat","schoolLat"))coordinate(b,k,90);for(String k:List.of("homeLng","schoolLng"))coordinate(b,k,180);var result=new ArrayList<Map<String,Object>>();for(var row:s.db.queryForList("SELECT l.*,u.name,u.phone,u.profile FROM sr_driver_listing l JOIN sr_user u ON u.id=l.driver_id WHERE l.available=true")){Map<String,Object>r=s.decode(row.get("route_details"));var rating=Ratings.summary(s,row.get("driver_id"));if(!Ratings.recommended(rating))continue;int remaining=seats(row.get("driver_id"));if((enabled(r,"limitEnrolment")&&remaining==0)||!matches(r,b))continue;Map<String,Object>profile=s.decode(row.get("profile"));var card=new LinkedHashMap<String,Object>();for(String key:List.of("driver_id","name","phone"))card.put(key,row.get(key));card.putAll(rating);card.put("vehicleModel",profile.get("vehicleModel"));card.put("plateNumber",profile.get("plateNumber"));card.put("capacity",profile.get("capacity"));card.put("seats",remaining);card.put("route",r);card.put("licenceAvailable",Boolean.TRUE.equals(row.get("share_licence"))&&s.db.queryForObject("SELECT count(*) FROM sr_document WHERE user_id=?",Integer.class,row.get("driver_id"))>0);result.add(card);}result.sort(Comparator.comparingDouble((Map<String,Object> card)->((Number)card.get("averageRating")).doubleValue()).reversed());return result;}
 @GetMapping("/drivers/{id}/licence") ResponseEntity<byte[]> licence(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id)throws Exception{var u=s.user(a);s.role(u,"PARENT");s.one("SELECT driver_id FROM sr_driver_listing WHERE driver_id=? AND available=true AND share_licence=true",id);var d=s.one("SELECT * FROM sr_document WHERE user_id=? ORDER BY created_at DESC LIMIT 1",id);return ResponseEntity.ok().header("Cache-Control","no-store").contentType(MediaType.parseMediaType(d.get("mime").toString())).body(Files.readAllBytes(uploads.resolve(d.get("id").toString())));}
 Map<String,Object> details(Map<String,Object>b){var d=new LinkedHashMap<String,Object>();for(String k:List.of("name","grade","homeAddress","homeGate","schoolName","schoolAddress","schoolGate","collectionContact"))d.put(k,text(b,k,300));for(String k:List.of("homeLat","schoolLat"))d.put(k,coordinate(b,k,90));for(String k:List.of("homeLng","schoolLng"))d.put(k,coordinate(b,k,180));if(b.get("dateOfBirth")!=null&&!b.get("dateOfBirth").toString().isBlank()){try{var dob=LocalDate.parse(b.get("dateOfBirth").toString());if(dob.isAfter(LocalDate.now(ZONE)))throw error(400,"Date of birth cannot be in the future");d.put("dateOfBirth",dob.toString());}catch(java.time.format.DateTimeParseException e){throw error(400,"Invalid date of birth");}}return d;}
 @PostMapping("/requests") @Transactional Object request(@RequestHeader(value="Authorization",required=false)String a,@RequestBody Map<String,Object>b){var u=s.user(a);s.role(u,"PARENT");String driver=text(b,"driverId",36);s.one("SELECT id FROM sr_user WHERE id=? AND role='DRIVER' FOR UPDATE",driver);var listing=s.one("SELECT * FROM sr_driver_listing WHERE driver_id=? AND available=true",driver);var d=details(b);if(!Ratings.recommended(Ratings.summary(s,driver)))throw error(409,"This driver is no longer recommended. Refresh your search.");if(!matches(s.decode(listing.get("route_details")),d)||(enabled(s.decode(listing.get("route_details")),"limitEnrolment")&&seats(driver)==0))throw error(409,"This driver is no longer available for this route");
  String from=text(b,"termStart",10),to=text(b,"termEnd",10);try{var start=LocalDate.parse(from);var end=LocalDate.parse(to);if(end.isBefore(start)||end.isAfter(start.plusYears(1))||end.isBefore(LocalDate.now(ZONE)))throw error(400,"Choose valid term dates");}catch(java.time.format.DateTimeParseException e){throw error(400,"Use YYYY-MM-DD dates");}
  if(!(b.get("week") instanceof Map<?,?>week)||week.isEmpty())throw error(400,"Provide a weekly timetable");int legCount=0;for(var key:week.keySet()){if(!key.toString().matches("[1-7]"))throw error(400,"Invalid weekday");var legs=journeys.legs(week.get(key));legCount+=legs.size();for(var leg:legs){if(leg.get("schoolFinishTime")==null||!LocalTime.parse(leg.get("schoolFinishTime").toString()).isAfter(LocalTime.parse(leg.get("arrivalBy").toString())))throw error(400,"Knock-off must be after arrival at school");}}if(legCount==0)throw error(400,"Choose at least one transport day");
  for(var old:s.db.queryForList("SELECT details FROM sr_passenger_request WHERE parent_id=? AND driver_id=? AND state='PENDING'",u.get("id"),driver)){Map<String,Object>previous=s.decode(old.get("details"));if(previous.get("name").toString().equalsIgnoreCase(d.get("name").toString()))throw error(409,"A request for this child is already pending");}
  d.put("termStart",from);d.put("termEnd",to);d.put("week",week);String id=id();s.db.update("INSERT INTO sr_passenger_request(id,parent_id,driver_id,details,state) VALUES(?,?,?,?,?)",id,u.get("id"),driver,s.encode(d),"PENDING");s.notifyUser(driver,"Passenger request","A parent has requested school transport. Review it in Passenger requests.",null);return Map.of("id",id,"state","PENDING");}
 @GetMapping("/requests") Object requests(@RequestHeader(value="Authorization",required=false)String a){var u=s.user(a);var rows=s.db.queryForList("SELECT r.*,p.name parent_name,p.phone parent_phone,d.name driver_name FROM sr_passenger_request r JOIN sr_user p ON p.id=r.parent_id JOIN sr_user d ON d.id=r.driver_id WHERE r.parent_id=? OR r.driver_id=? ORDER BY r.created_at DESC",u.get("id"),u.get("id"));for(var r:rows)r.put("details",s.decode(r.get("details")));return rows;}
 @PostMapping("/requests/{id}/{decision}") @Transactional Object decide(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id,@PathVariable String decision){var u=s.user(a);s.role(u,"DRIVER");if(!Set.of("approve","reject").contains(decision))throw error(400,"Invalid decision");s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",u.get("id"));var r=s.one("SELECT * FROM sr_passenger_request WHERE id=? AND driver_id=? FOR UPDATE",id,u.get("id"));if(!r.get("state").equals("PENDING"))return Map.of("state",r.get("state"));
  String child=null,state="REJECTED";if(decision.equals("approve")){var listing=s.one("SELECT route_details FROM sr_driver_listing WHERE driver_id=?",u.get("id"));if(enabled(s.decode(listing.get("route_details")),"limitEnrolment")&&seats(u.get("id"))==0)throw error(409,"Enrolment seat limit reached. Enable multiple trips in your route listing to accept more children.");Map<String,Object>d=s.decode(r.get("details"));var links=s.db.queryForList("SELECT id FROM sr_link WHERE parent_id=? AND driver_id=?",r.get("parent_id"),u.get("id"));String link=links.isEmpty()?id():links.get(0).get("id").toString();if(links.isEmpty())s.db.update("INSERT INTO sr_link VALUES(?,?,?)",link,r.get("parent_id"),u.get("id"));child=id();var detail=new LinkedHashMap<String,Object>(d);detail.remove("week");detail.remove("termStart");detail.remove("termEnd");s.db.update("INSERT INTO sr_child VALUES(?,?,?)",child,link,s.encode(detail));s.startChildBilling(child);s.db.update("INSERT INTO sr_schedule VALUES(?,?,?,?)",child,LocalDate.parse(d.get("termStart").toString()),LocalDate.parse(d.get("termEnd").toString()),s.encode(d.get("week")));state="APPROVED";}
  s.db.update("UPDATE sr_passenger_request SET state=?,child_id=? WHERE id=?",state,child,id);s.notifyUser(r.get("parent_id"),"Transport request "+state.toLowerCase(),state.equals("APPROVED")?"Your driver accepted. Your child and timetable are now linked. Monthly subscription coverage is still required.":"The driver could not accept this request. You can try another available driver.",child);return Map.of("state",state);
 }
}
